import { MakeLogicType, afterMount, connect, kea, listeners, path, selectors } from 'kea'
import posthog from 'posthog-js'

import { ConnectedApp, connectedAppsLogic } from 'scenes/settings/user/connectedAppsLogic'

const POLL_INTERVAL_MS = 3000

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface onboardingMcpStepLogicValues {
    connectedApps: ConnectedApp[] // connectedAppsLogic
    isMcpConnected: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface onboardingMcpStepLogicActions {
    loadConnectedApps: () => any // connectedAppsLogic
    loadConnectedAppsSuccess: (
        connectedApps: ConnectedApp[],
        payload?: any
    ) => {
        connectedApps: ConnectedApp[]
        payload?: any
    } // connectedAppsLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface onboardingMcpStepLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        isMcpConnected: (connectedApps: ConnectedApp[]) => boolean
    }
}

export type onboardingMcpStepLogicType = MakeLogicType<
    onboardingMcpStepLogicValues,
    onboardingMcpStepLogicActions,
    Record<string, any>,
    onboardingMcpStepLogicMeta
>

export const onboardingMcpStepLogic = kea<onboardingMcpStepLogicType>([
    path(['scenes', 'onboarding', 'simple', 'onboardingMcpStepLogic']),
    connect(() => ({
        values: [connectedAppsLogic, ['connectedApps']],
        actions: [connectedAppsLogic, ['loadConnectedApps', 'loadConnectedAppsSuccess']],
    })),
    selectors({
        // Any live OAuth connection counts: the MCP server signs in through OAuth, and the API does
        // not tell an MCP client apart from other OAuth apps.
        isMcpConnected: [
            (s) => [s.connectedApps],
            (connectedApps: ConnectedApp[]): boolean => connectedApps.length > 0,
        ],
    }),
    listeners(({ cache, values }) => ({
        loadConnectedAppsSuccess: () => {
            if (!values.isMcpConnected) {
                return
            }
            cache.disposables.dispose('poll')
            if (!cache.reportedConnected) {
                cache.reportedConnected = true
                // pinned: analytics event name, dashboards read it
                posthog.capture('onboarding mcp connected', { connected_apps: values.connectedApps.length })
            }
        },
    })),
    afterMount(({ actions, cache }) => {
        cache.disposables.add(() => {
            const id = window.setInterval(() => actions.loadConnectedApps(), POLL_INTERVAL_MS)
            return () => clearInterval(id)
        }, 'poll')
    }),
])
